import type { PluginSettings } from './interfaces/settings-interface'
import { escapeRegex, OBS_CODE_REGEXP, OBS_DISPLAY_CODE_REGEXP, OBS_INLINE_MATH_REGEXP, OBS_DISPLAY_MATH_REGEXP } from './constants'
import { ID_REGEXP_STR, TAG_REGEXP_STR } from './note'

export function cardSourceUrl(fileUrl: string, noteId: number): string {
    const url = new URL(fileUrl)
    url.hostname = 'anki-card'
    url.searchParams.set('nid', String(noteId))
    return url.toString()
}

// Replace only the link generated by FormatConverter, preserving the label,
// other links, and any context/aliases appended to the same field.
export function cardSourceLinkFields(fields: Record<string, string>, field: string, fileUrl: string, noteId: number): Record<string, string> {
    if (!field || !fileUrl || !Number.isSafeInteger(noteId) || noteId <= 0 || !fields[field]) return {}
    const source = `href="${fileUrl}" class="obsidian-link"`
    if (!fields[field].includes(source)) return {}
    return {
        [field]: fields[field].replace(source, `href="${cardSourceUrl(fileUrl, noteId)}" class="obsidian-link"`)
    }
}

type NavigationSettings = Pick<PluginSettings, 'Syntax' | 'CUSTOM_REGEXPS'>

/** Resolve against current text, not saved line numbers. No Anki connection needed. */
export function findCardSource(text: string, noteId: number, settings?: NavigationSettings): number | null {
    if (!Number.isSafeInteger(noteId) || noteId <= 0) return null
    if (text.includes('\r\n')) {
        // User regexes generally use \n. Match normalized text, then translate
        // back to an offset in the editor's original (possibly mixed) newlines.
        const offset = findCardSource(text.replace(/\r\n/g, '\n'), noteId, settings)
        if (offset === null) return null
        let originalOffset = offset
        for (const newline of text.matchAll(/\r\n/g)) {
            if (newline.index >= originalOffset) break
            originalOffset++
        }
        return originalOffset
    }
    const frontmatter = /^---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/.exec(text)
    const hasFrontmatterId = frontmatter && new RegExp(
        String.raw`^nid:[ \t]*["']?${noteId}["']?[ \t]*(?:#.*)?\r?$`, 'm'
    ).test(frontmatter[0])
    const markers = hasFrontmatterId ? [] : Array.from(text.matchAll(new RegExp(String.raw`(?:<!--)?\bID: ${noteId}(?!\d)`, 'g')))
    if (!markers.length && !hasFrontmatterId) return null

    const syntax = settings?.Syntax
    const patterns = [
        new RegExp('^' + escapeRegex(syntax?.['Begin Note'] ?? 'START') + String.raw`\r?\n[\s\S]*?\r?\n` + escapeRegex(syntax?.['End Note'] ?? 'END'), 'gm'),
        new RegExp(escapeRegex(syntax?.['Begin Inline Note'] ?? 'STARTI') + '.*?' + escapeRegex(syntax?.['End Inline Note'] ?? 'ENDI'), 'g')
    ]
    const bodyStart = frontmatter ? frontmatter[0].length : 0
    const starts: number[] = []
    const ignored: Array<[number, number]> = []
    const containsMarker = (match: RegExpMatchArray) => markers.some(marker => marker.index >= match.index && marker.index < match.index + match[0].length)
    for (const pattern of patterns) {
        for (const match of text.matchAll(pattern)) {
            if (containsMarker(match)) return match.index
            if (hasFrontmatterId && match.index >= bodyStart) starts.push(match.index)
            ignored.push([match.index, match.index + match[0].length])
        }
    }
    // As in AllFile.search(), regex cards must not be claimed from regular
    // cards, code/math examples, or frozen fields.
    const excludedPatterns = [OBS_CODE_REGEXP, OBS_DISPLAY_CODE_REGEXP, OBS_INLINE_MATH_REGEXP, OBS_DISPLAY_MATH_REGEXP]
    if (syntax?.['Frozen Fields Line']) {
        excludedPatterns.push(new RegExp(escapeRegex(syntax['Frozen Fields Line']) + String.raw` - (.*?):\n((?:[^\n][\n]?)+)`, 'g'))
    }
    for (const pattern of excludedPatterns) {
        for (const match of text.matchAll(pattern)) ignored.push([match.index, match.index + match[0].length])
    }
    for (const source of Object.values(settings?.CUSTOM_REGEXPS ?? {})) {
        if (!source) continue
        // Match the same optional Tags:/ID suffixes as the sync parser. Invalid
        // or since-edited regex settings must not prevent jumping to the ID.
        for (const tags of ['', TAG_REGEXP_STR]) {
            try {
                const pattern = new RegExp(source + tags + (hasFrontmatterId ? '' : ID_REGEXP_STR), 'gm')
                for (const match of text.matchAll(pattern)) {
                    if (ignored.some(([start, end]) => match.index >= start - 1 && match.index + match[0].length <= end + 1)) continue
                    if (containsMarker(match) && Number(match[match.length - 1]) === noteId) return match.index
                    if (hasFrontmatterId && match.index >= bodyStart) starts.push(match.index)
                }
            } catch {
                // Fall back to the ID marker (or the file body for YAML IDs).
            }
        }
    }
    if (markers.length) return markers[0].index
    return starts.length ? Math.min(...starts) : bodyStart
}
